import * as api from "./base";

export interface IssueClientCertificate {
	name: string;
	validityDays: number;
	format: "pkcs12" | "pem";
	password?: string;
}

/**
 * The private key is generated by the server for this request only and is never stored,
 * so the response is downloaded straight away and can't be fetched again.
 */
export async function issueClientCertificate(caId: number, item: IssueClientCertificate): Promise<void> {
	await api.postDownload(
		{
			url: `/nginx/client-cas/${caId}/certificates`,
			data: item,
		},
		`client.${item.format === "pem" ? "pem" : "p12"}`,
	);
}
